  listGenerations: {
    parameters: {
      query?: {
        from?: string;
        to?: string;
        cursor?: string;
        limit?: number;
        api_key_id?: string;
        model?: string;
        search?: string;
        sort?: "newest" | "highest_cost";
        status?: "succeeded" | "failed" | "cancelled" | "abandoned";
        /** @description Exact task identifier supplied in the capture header. */
        task_id?: string;
      };
      header?: never;
      path: {
        workspace_id: string;
      };
      cookie?: never;
    };
    requestBody?: never;
    responses: {
      /** @description Workspace generations. With task_id, returns captured metadata from S3; date-range queries return hosted usage logs. */
      200: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          "application/json":
            | components["schemas"]["TraceGenerationList"]
            | {
                data: {
                  /**
                   * Format: uuid
                   * @example 0198ae50-94d8-7d4d-a8be-9f9b44b8c774
                   */
                  id: string;
                  external_id: string | null;
                  model_id: string;
                  /** @enum {string} */
                  status: "succeeded" | "failed" | "cancelled" | "abandoned";
                  streamed: boolean;
                  charge: string;
                  input_tokens: number;
                  cached_input_tokens: number;
                  cache_write_tokens: number;
                  output_tokens: number;
                  reasoning_tokens: number;
                  finish_reason: string | null;
                  error_code: string | null;
                  usable_output_delivered: boolean;
                  /** @enum {string|null} */
                  cancellation_owner: "client" | "server" | "runtime" | null;
                  /**
                   * Format: date-time
                   * @example 2026-08-16T12:00:00.000Z
                   */
                  received_at: string;
                  /**
                   * Format: date-time
                   * @example 2026-08-16T12:00:00.000Z
                   */
                  started_at: string | null;
                  /**
                   * Format: date-time
                   * @example 2026-08-16T12:00:00.000Z
                   */
                  first_token_at: string | null;
                  /**
                   * Format: date-time
                   * @example 2026-08-16T12:00:00.000Z
                   */
                  completed_at: string;
                }[];
                next_cursor: string | null;
              };
        };
      };
      /** @description Authentication is required. */
      401: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          "application/problem+json": components["schemas"]["Problem"];
        };
      };
      /** @description The workspace was not found. */
      404: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          "application/problem+json": components["schemas"]["Problem"];
        };
      };
      /** @description The filters are invalid. */
      422: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          "application/problem+json": components["schemas"]["Problem"];
        };
      };
      /** @description Generation logs are unavailable. */
      503: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          "application/problem+json": components["schemas"]["Problem"];
        };
      };
    };
  };
